#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<unsigned long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    int n1 = n / 2;
    vector<unsigned long long> a1, a2;

    function<void(int, unsigned long long)> sums1 = [&](int i, unsigned long long sum) {
        if (i == n1) {
            a1.push_back(sum);
        } else {
            sums1(i + 1, (sum + a[i]) % m);
            sums1(i + 1, sum);
        }
    };

    function<void(int, unsigned long long)> sums2 = [&](int i, unsigned long long sum) {
        if (i == n) {
            a2.push_back(sum);
        } else {
            sums2(i + 1, (sum + a[i]) % m);
            sums2(i + 1, sum);
        }
    };

    sums1(0, 0ULL);
    sums2(n1, 0ULL);

    unsigned long long ans = 0;
    sort(a1.begin(), a1.end());
    a1.erase(unique(a1.begin(), a1.end()), a1.end());

    for (auto i : a2) {
        auto it = lower_bound(a1.begin(), a1.end(), m - i);
        if (it != a1.begin()) {
            --it;
            unsigned long long candidate = *it + i;
            if (candidate > ans) {
                ans = candidate;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

